/* From Uiverse.io by Nawsome - Tags: button */
.__UIV_SCOPE__ .arrow {
  cursor: pointer;
  height: 60px;
  left: 50%;
  position: absolute;
  top: 50%;
  transform: translateX(-50%) translateY(-50%);
  transition: transform 0.1s;
  width: 50px;
}

.__UIV_SCOPE__ .arrow-top, .__UIV_SCOPE__ .arrow-bottom {
  background-color: #666;
  height: 4px;
  left: -5px;
  position: absolute;
  top: 50%;
  width: 100%;
}

.__UIV_SCOPE__ .arrow-top:after, .__UIV_SCOPE__ .arrow-bottom:after {
  background-color: #fff;
  content: "";
  height: 100%;
  position: absolute;
  top: 0;
  transition: all 0.15s;
}

.__UIV_SCOPE__ .arrow-top {
  transform: rotate(45deg);
  transform-origin: bottom right;
}

.__UIV_SCOPE__ .arrow-top:after {
  left: 100%;
  right: 0;
  transition-delay: 0s;
}

.__UIV_SCOPE__ .arrow-bottom {
  transform: rotate(-45deg);
  transform-origin: top right;
}

.__UIV_SCOPE__ .arrow-bottom:after {
  left: 0;
  right: 100%;
  transition-delay: 0.15s;
}

.__UIV_SCOPE__ .arrow:hover .arrow-top:after {
  left: 0;
  transition-delay: 0.15s;
}

.__UIV_SCOPE__ .arrow:hover .arrow-bottom:after {
  right: 0;
  transition-delay: 0s;
}

.__UIV_SCOPE__ .arrow:active {
  transform: translateX(-50%) translateY(-50%) scale(0.9);
}
